    ((info.data.lots && info.data.lots.table) || []).forEach((f, i) => {
      const n = i + 1;
      rows.push([ `lote.${n}.tamano`, `Tamaño de lote ${n}: tamaño`, f.size ]);
      rows.push([ `lote.${n}.peso`, `Tamaño de lote ${n}: peso`, f.weight ]);
    });

